-- ============================================================
-- STAFF COMPLIANCE MODULE — complete setup, one file.
--
-- Paste the whole thing into the Supabase SQL editor and run once.
-- Idempotent end to end; running it twice is safe.
--
-- Does NOT touch the patient-side tables in the public schema —
-- supabase/schema.sql is separate.
--
-- GENERATED by scripts/build-staff-setup.sh. Edit the source migrations,
-- then re-run that script; do not edit this file directly.
--
-- Two things remain afterwards and neither can be done in SQL:
--   alter role staff_app with password '<generate one>';
--   insert into staff.org_invites (org_slug, email, role)
--     values ('afc', '<your work email>', 'org_admin');
-- ============================================================


-- ========== staff-schema.sql ==========

-- ============================================================
-- STAFF COMPLIANCE & INTERNAL OPS — schema
--
-- Run AFTER supabase/schema.sql. Idempotent; safe to re-run.
--
-- Everything here lives in a dedicated `staff` schema, deliberately
-- separate from the public-schema patient-triage tables (clinics, clicks,
-- conversations, ...). There are NO foreign keys from staff.* into those
-- tables and none the other way. The patient side is anonymous and stores
-- no PHI; this side has named accounts and internal operational data.
-- Keeping them in different schemas means a query written against one can
-- never silently reach the other, and RLS policies can't be confused
-- between them.
--
-- ORG REGISTRY — read before changing.
-- The public schema already has a `tenants` table (slug, display_name,
-- active) which is what resolves afc.medicin.io to a brand today.
-- staff.orgs deliberately does NOT foreign-key to it, but DOES use the
-- same slug as its primary key. So there is one shared vocabulary for
-- "which org is this" and no cross-schema dependency: a staff org exists
-- only if someone creates it here, and deleting a tenant can't cascade
-- into staff records. The slug is the contract.
-- ============================================================

create schema if not exists staff;

-- ============================================================
-- ORGS & USERS
-- ============================================================

create table if not exists staff.orgs (
  slug        text primary key,          -- matches public.tenants.slug by convention, not by FK
  name        text not null,
  plan        text not null default 'internal',
  active      boolean not null default true,
  created_at  timestamptz not null default now()
);

-- Roles are a fixed vocabulary, enforced in the database rather than only
-- in application code — a bug in a route handler shouldn't be able to
-- invent a role that RLS doesn't understand.
do $$ begin
  create type staff.user_role as enum (
    'platform_super_admin',   -- global; the only role not scoped to one org
    'org_admin',
    'clinical_lead',
    'staff'
  );
exception when duplicate_object then null;
end $$;

create table if not exists staff.users (
  id          uuid primary key default gen_random_uuid(),
  google_sub  text,                      -- Google's stable subject id; set on first sign-in
  email       text not null,
  name        text,
  org_slug    text references staff.orgs(slug) on delete restrict,
  role        staff.user_role not null default 'staff',
  active      boolean not null default true,
  created_at  timestamptz not null default now(),
  last_seen_at timestamptz,
  -- Every role except the platform super admin must belong to an org.
  constraint staff_users_org_required
    check (role = 'platform_super_admin' or org_slug is not null)
);

-- Identity is unique WITHIN an org, not globally. One person can be staff
-- at two franchises with the same Google account, and a global unique on
-- google_sub would make the second org's invite fail with a constraint
-- error that looks like a bug.
alter table staff.users drop constraint if exists staff_users_google_sub_key;

create unique index if not exists staff_users_email_org
  on staff.users (lower(email), coalesce(org_slug, ''));

create unique index if not exists staff_users_google_org
  on staff.users (google_sub, coalesce(org_slug, '')) where google_sub is not null;

-- INVITES — the actual access control.
-- "Sign in with Google" is authentication, not authorization: without this
-- table anyone with a Google account could create a session. A sign-in is
-- only accepted if the email matches an invite row (or its domain matches
-- an org's allow-listed domain), and no match must deny with a clear
-- message rather than silently creating an account.
create table if not exists staff.org_invites (
  id          uuid primary key default gen_random_uuid(),
  org_slug    text not null references staff.orgs(slug) on delete cascade,
  email       text,                      -- exact address, OR
  email_domain text,                     -- everyone at a domain, e.g. 'buchmedical.com'
  role        staff.user_role not null default 'staff',
  invited_by  uuid references staff.users(id),
  created_at  timestamptz not null default now(),
  revoked_at  timestamptz,
  constraint staff_invite_target
    check ((email is not null) <> (email_domain is not null))
);

create index if not exists staff_invites_lookup
  on staff.org_invites (lower(coalesce(email, email_domain))) where revoked_at is null;

-- ============================================================
-- FORMS
-- ============================================================

create table if not exists staff.form_templates (
  id          uuid primary key default gen_random_uuid(),
  org_slug    text not null references staff.orgs(slug) on delete cascade,
  name        text not null,
  category    text,
  -- The whole point of the form builder: a template is data, not code, so
  -- the 8 seeded logs are ordinary rows rather than special-cased forms.
  schema_json jsonb not null,
  frequency   text not null,             -- 'daily' | 'weekly' | 'monthly' | 'quarterly' | 'per_shift'
  version     integer not null default 1,
  active      boolean not null default true,
  created_by  uuid references staff.users(id),
  created_at  timestamptz not null default now()
);

create index if not exists staff_templates_org on staff.form_templates (org_slug) where active;

create table if not exists staff.form_instances (
  id           uuid primary key default gen_random_uuid(),
  template_id  uuid not null references staff.form_templates(id) on delete cascade,
  org_slug     text not null references staff.orgs(slug) on delete cascade,
  due_date     date not null,
  assigned_to  uuid references staff.users(id),
  status       text not null default 'due',   -- due | submitted | approved | flagged
  created_at   timestamptz not null default now(),
  -- One instance per template per due date; makes the scheduled generator
  -- safely re-runnable instead of producing duplicates on a retry.
  unique (template_id, due_date)
);

create index if not exists staff_instances_org_status
  on staff.form_instances (org_slug, status, due_date);

create table if not exists staff.form_responses (
  id           uuid primary key default gen_random_uuid(),
  instance_id  uuid not null references staff.form_instances(id) on delete cascade,
  org_slug     text not null references staff.orgs(slug) on delete cascade,
  submitted_by uuid not null references staff.users(id),
  submitted_at timestamptz not null default now(),
  answers_json jsonb not null,
  status       text not null default 'pending',  -- pending | approved | flagged
  -- Corrections create a NEW response pointing at the one it supersedes.
  -- A compliance log that can be silently edited after the fact is not
  -- evidence of anything.
  supersedes_id uuid references staff.form_responses(id)
);

create index if not exists staff_responses_instance on staff.form_responses (instance_id);

create table if not exists staff.attachments (
  id           uuid primary key default gen_random_uuid(),
  response_id  uuid not null references staff.form_responses(id) on delete cascade,
  org_slug     text not null references staff.orgs(slug) on delete cascade,
  kind         text not null default 'photo',    -- photo | file
  storage_path text not null,
  note         text,
  -- Staff phones can catch a patient or a screen in the background. The
  -- uploader affirms they checked; the affirmation is recorded with the
  -- file rather than living only in a policy document.
  no_pii_confirmed boolean not null default false,
  uploaded_by  uuid not null references staff.users(id),
  created_at   timestamptz not null default now()
);

create table if not exists staff.review_actions (
  id           uuid primary key default gen_random_uuid(),
  response_id  uuid not null references staff.form_responses(id) on delete cascade,
  org_slug     text not null references staff.orgs(slug) on delete cascade,
  reviewer_id  uuid not null references staff.users(id),
  action       text not null,                    -- approved | flagged | commented
  note         text,
  created_at   timestamptz not null default now()
);

-- ============================================================
-- AUDIT
-- ============================================================

create table if not exists staff.audit_log (
  id          bigserial primary key,
  org_slug    text,
  actor_id    uuid references staff.users(id),
  action      text not null,
  entity      text,
  entity_id   text,
  detail      jsonb,
  created_at  timestamptz not null default now()
);

create index if not exists staff_audit_org_time on staff.audit_log (org_slug, created_at desc);

-- ============================================================
-- ROW-LEVEL SECURITY
--
-- Isolation is enforced here, not in route handlers. The org a request
-- belongs to is never taken from the client.
--
-- current_setting('staff.org_slug') and ('staff.role') are set per
-- connection by the server after it has resolved the session — see
-- lib/staff/db.ts. A connection that hasn't set them sees nothing, which
-- is the correct failure mode: a forgotten SET yields an empty result,
-- not someone else's data.
-- ============================================================

create or replace function staff.current_org() returns text
language sql stable as $$
  select nullif(current_setting('staff.org_slug', true), '')
$$;

create or replace function staff.is_super_admin() returns boolean
language sql stable as $$
  select coalesce(current_setting('staff.role', true), '') = 'platform_super_admin'
$$;

do $$
declare t text;
begin
  foreach t in array array[
    'orgs','users','org_invites','form_templates','form_instances',
    'form_responses','attachments','review_actions','audit_log'
  ] loop
    execute format('alter table staff.%I enable row level security', t);
    execute format('alter table staff.%I force row level security', t);
  end loop;
end $$;

-- Every org-scoped table gets the same shape of policy: your org, or you
-- are the platform super admin.
do $$
declare t text;
begin
  foreach t in array array[
    'users','org_invites','form_templates','form_instances',
    'form_responses','attachments','review_actions','audit_log'
  ] loop
    execute format('drop policy if exists staff_org_isolation on staff.%I', t);
    execute format($f$
      create policy staff_org_isolation on staff.%I
        for all
        using (staff.is_super_admin() or org_slug = staff.current_org())
        with check (staff.is_super_admin() or org_slug = staff.current_org())
    $f$, t);
  end loop;
end $$;

drop policy if exists staff_orgs_isolation on staff.orgs;
create policy staff_orgs_isolation on staff.orgs
  for all
  using (staff.is_super_admin() or slug = staff.current_org())
  with check (staff.is_super_admin());

-- ============================================================
-- APPLICATION ROLE
--
-- The app connects as this role, NOT as `postgres`. A superuser bypasses
-- row-level security entirely, which would turn every policy above into
-- decoration while still looking correct in code review. This role has no
-- BYPASSRLS and owns nothing, so the policies actually apply to it.
--
-- Set the password yourself and put the resulting connection string in
-- STAFF_DATABASE_URL:
--
--   alter role staff_app with password 'a-long-random-password';
--
--   STAFF_DATABASE_URL=postgresql://staff_app:<password>@<host>:6543/postgres
-- ============================================================

do $$ begin
  create role staff_app with login password null;
exception when duplicate_object then null;
end $$;

grant usage on schema staff to staff_app;
grant select, insert, update, delete on all tables in schema staff to staff_app;
grant usage, select on all sequences in schema staff to staff_app;
alter default privileges in schema staff
  grant select, insert, update, delete on tables to staff_app;
alter default privileges in schema staff
  grant usage, select on sequences to staff_app;

-- ============================================================
-- SEED — the first org.
-- Slug matches public.tenants.slug ('afc') by convention so the staff area
-- and the patient portal agree on what "afc" means.
-- ============================================================

-- Keep `name` matching public.tenants.display_name for the same slug. They
-- are separate columns in separate schemas on purpose, but a staff screen
-- shows the tenant's display name in the header and this one in the body,
-- and two different names for one clinic on one screen reads as a bug.
insert into staff.orgs (slug, name, plan)
values ('afc', 'AFC Urgent Care', 'internal')
on conflict (slug) do nothing;

-- ============================================================
-- Done. Next:
--
--   1. alter role staff_app with password '…'  (see above)
--   2. Set these env vars:
--        STAFF_DATABASE_URL       postgres://staff_app:…  (pooler, port 6543)
--        STAFF_SESSION_SECRET     32+ random characters
--        GOOGLE_OAUTH_CLIENT_ID
--        GOOGLE_OAUTH_CLIENT_SECRET
--   3. In the Google Cloud console, add
--        https://afc.medicin.io/api/staff/auth/callback
--      as an authorized redirect URI (one per staff hostname).
--   4. Add the first invite —
--
--   insert into staff.org_invites (org_slug, email_domain, role)
--   values ('afc', 'buchmedical.com', 'staff');
--
--   insert into staff.org_invites (org_slug, email, role)
--   values ('afc', 'you@example.com', 'org_admin');
--
-- Until an invite exists, every Google sign-in is correctly denied.
-- ============================================================


-- ========== staff-onboarding.sql ==========

-- ============================================================
-- STAFF ONBOARDING & PER-EMPLOYEE COMPLIANCE RECORD
--
-- Run AFTER supabase/staff-schema.sql. Idempotent; safe to re-run.
--
-- The point of this file is a record that answers one question about any
-- employee on any date: what were they told, when did they say they
-- understood it, and what exactly did the document say at the moment they
-- signed it. "Nobody told me" has to be a checkable claim, not an
-- argument.
--
-- Three things make that work, and each is a constraint here rather than
-- a convention in application code:
--
--  1. DOCUMENTS ARE IMMUTABLE ONCE SIGNED. Editing a policy creates a new
--     version row. A signature points at one version, so revising a policy
--     can never rewrite what somebody already attested to.
--
--  2. THE SIGNATURE STORES A HASH OF THE TEXT IT SIGNED. Even if a row were
--     tampered with, the hash recorded at signing time no longer matches,
--     and the record shows it. The evidence does not depend on trusting
--     the database it lives in.
--
--  3. ASSIGNMENT IS DERIVED, NOT STORED. Who owes what is computed from
--     the published documents for someone's role minus the signatures they
--     already have. There is no per-user checklist to fall out of sync,
--     so a new hire cannot be quietly missing an item because a row was
--     never created for them.
--
-- E-SIGN / UETA: an electronic signature needs intent to sign, consent to
-- transact electronically, the signature associated with the record, and
-- retention of the record. Each has a column below. This is not legal
-- advice — have an employment attorney review the attestation wording and
-- the retention period before this becomes the system of record.
-- ============================================================

-- ============================================================
-- WHO THE PERSON IS
--
-- A signature needs a legal name, and "the name on the Google account" is
-- not it — plenty of staff sign in as "Katie" and sign documents as
-- "Kathryn A. Nguyen". Captured once, on first run.
-- ============================================================

alter table staff.users add column if not exists legal_name  text;
alter table staff.users add column if not exists job_title   text;
alter table staff.users add column if not exists start_date  date;
-- Consent to receive and sign records electronically, with the moment it
-- was given. Without this the signatures below are weaker evidence.
alter table staff.users add column if not exists esign_consented_at timestamptz;

-- ============================================================
-- POLICY & TRAINING DOCUMENTS
-- ============================================================

create table if not exists staff.policy_docs (
  id           uuid primary key default gen_random_uuid(),
  org_slug     text not null references staff.orgs(slug) on delete cascade,
  -- Stable across versions. A signature records both the key and the
  -- version, so "has this person acknowledged the HIPAA policy" survives
  -- the policy being rewritten.
  key          text not null,
  version      integer not null default 1,
  title        text not null,
  category     text,                       -- hipaa | osha | clinical | hr | operations
  -- The rule this document exists because of, shown to the reader. An
  -- acknowledgement that cites its own authority is much harder to wave
  -- away later than one that doesn't.
  citation     text,
  summary      text,
  body_md      text not null,
  -- The sentence the person is actually agreeing to. Stored per document
  -- and copied into the signature, because the wording is the substance
  -- of what was agreed.
  attestation  text not null default
    'I have read and understand this document, and I agree to follow it in my work.',
  -- null = everyone. Otherwise only these roles are assigned it.
  applies_to   staff.user_role[],
  -- Annual retraining and the like: after this many months the
  -- acknowledgement expires and the document is assigned again.
  renew_months integer,
  sort_order   integer not null default 100,
  -- DRAFTS ARE NOT ASSIGNED TO ANYONE. A seeded skeleton must not be
  -- presented to staff as their employer's policy, and an organization
  -- must not be able to claim someone acknowledged a document that was
  -- still being written.
  published_at timestamptz,
  active       boolean not null default true,
  created_by   uuid references staff.users(id),
  created_at   timestamptz not null default now(),
  unique (org_slug, key, version)
);

create index if not exists staff_docs_assignable
  on staff.policy_docs (org_slug, sort_order)
  where active and published_at is not null;

-- ============================================================
-- SIGNATURES — the evidence
-- ============================================================

create table if not exists staff.attestations (
  id           uuid primary key default gen_random_uuid(),
  org_slug     text not null references staff.orgs(slug) on delete cascade,
  user_id      uuid not null references staff.users(id) on delete restrict,
  doc_id       uuid not null references staff.policy_docs(id) on delete restrict,
  -- Denormalized on purpose: this row has to stay readable as evidence
  -- even if the document row is ever removed, and a join is not a thing
  -- you want between you and an answer in a deposition.
  doc_key      text not null,
  doc_version  integer not null,
  doc_title    text not null,
  -- sha256 of body_md exactly as rendered to this person. Computed
  -- server-side from the stored document, never accepted from the client.
  body_sha256  text not null,
  -- The attestation sentence as it was shown, not as it reads today.
  statement    text not null,
  -- Typed legal name. The intent-to-sign act.
  typed_name   text not null,
  -- The drawn signature, as SVG path data rather than an image: a few
  -- hundred bytes, diffable, and printable at any size.
  signature_path text,
  signed_at    timestamptz not null default now(),
  -- Circumstances of signing. Retained because "someone else signed for
  -- me" is the usual challenge to an electronic signature.
  signed_ip    text,
  user_agent   text,
  -- Renewals: the previous signature is kept and pointed at, never
  -- replaced. A compliance history with gaps edited out is not a history.
  supersedes_id uuid references staff.attestations(id),
  -- One live signature per person per document version. A renewal is a
  -- new version of the document, so this does not block annual retraining.
  unique (user_id, doc_id)
);

create index if not exists staff_attest_user on staff.attestations (user_id, signed_at desc);
create index if not exists staff_attest_doc  on staff.attestations (doc_id);

-- Nothing may edit or delete a signature. Not the app, not an admin, not
-- a migration that means well. A record that can be adjusted after the
-- fact proves nothing about what happened before it.
create or replace function staff.attestations_are_append_only()
returns trigger language plpgsql as $$
begin
  raise exception
    'staff.attestations is append-only: a signature cannot be % after the fact',
    lower(tg_op);
end $$;

drop trigger if exists staff_attest_no_change on staff.attestations;
create trigger staff_attest_no_change
  before update or delete on staff.attestations
  for each row execute function staff.attestations_are_append_only();

-- ============================================================
-- RLS — same shape as the rest of the staff schema
-- ============================================================

do $$
declare t text;
begin
  foreach t in array array['policy_docs','attestations'] loop
    execute format('alter table staff.%I enable row level security', t);
    execute format('alter table staff.%I force row level security', t);
    execute format('drop policy if exists staff_org_isolation on staff.%I', t);
    execute format($f$
      create policy staff_org_isolation on staff.%I
        for all
        using (staff.is_super_admin() or org_slug = staff.current_org())
        with check (staff.is_super_admin() or org_slug = staff.current_org())
    $f$, t);
  end loop;
end $$;

grant select, insert, update, delete on staff.policy_docs to staff_app;
-- Insert and select only. The trigger above would reject an update anyway;
-- withholding the privilege means the attempt never reaches it.
grant select, insert on staff.attestations to staff_app;

-- ============================================================
-- WHAT EACH PERSON STILL OWES
--
-- A view rather than a table, so it cannot disagree with the underlying
-- facts.
--
-- security_invoker IS WHAT MAKES THIS SAFE. A Postgres view normally runs
-- with its OWNER's privileges, which means a view owned by `postgres`
-- reads straight past the row-level security of whoever queries it — the
-- classic way an RLS-protected schema springs a leak through a
-- convenience view. With security_invoker the view evaluates under the
-- caller, so it is org-scoped by the same policies as the tables.
--
-- A document is outstanding when it is published, applies to your role,
-- and either you have never signed that version or your signature has
-- aged past the document's renewal window.
-- ============================================================

-- Dropped first rather than CREATE OR REPLACE: replace can only APPEND
-- columns to a view, so once a later migration extends this one, the
-- combined setup file's second run fails here with "cannot drop
-- columns from view" while its first run was clean. Drop-first makes
-- every view definition rerunnable regardless of what extends it.
--
-- CASCADE is safe here and is not a shrug: views in this schema are
-- defined in dependency order within the combined setup file, so a
-- cascade only ever drops a view that is recreated further down the
-- same file. compliance_status builds on outstanding_docs, which is
-- why a bare drop failed.
drop view if exists staff.outstanding_docs cascade;
create view staff.outstanding_docs
with (security_invoker = true) as
select
  u.id                          as user_id,
  u.org_slug,
  d.id                          as doc_id,
  d.key                         as doc_key,
  d.version,
  d.title,
  d.category,
  d.citation,
  d.summary,
  d.sort_order,
  d.renew_months,
  a.signed_at                   as previously_signed_at,
  case
    when a.id is null then 'never'
    else 'expired'
  end                           as reason
from staff.users u
join staff.policy_docs d
  on d.org_slug = u.org_slug
 and d.active
 and d.published_at is not null
 and (d.applies_to is null or u.role = any (d.applies_to))
left join staff.attestations a
  on a.user_id = u.id
 and a.doc_key = d.key
 and a.doc_version = d.version
where u.active
  and (
    a.id is null
    or (d.renew_months is not null
        and a.signed_at < now() - make_interval(months => d.renew_months))
  );

grant select on staff.outstanding_docs to staff_app;

-- Completion per person, for the admin roster: how many documents apply
-- to them and how many they have live signatures for.
-- Dropped first rather than CREATE OR REPLACE: replace can only APPEND
-- columns to a view, so once a later migration extends this one, the
-- combined setup file's second run fails here with "cannot drop
-- columns from view" while its first run was clean. Drop-first makes
-- every view definition rerunnable regardless of what extends it.
drop view if exists staff.compliance_status cascade;
create view staff.compliance_status
with (security_invoker = true) as
select
  u.id            as user_id,
  u.org_slug,
  u.email,
  u.legal_name,
  u.name,
  u.job_title,
  u.role,
  u.start_date,
  u.esign_consented_at,
  (select count(*)
     from staff.policy_docs d
    where d.org_slug = u.org_slug
      and d.active
      and d.published_at is not null
      and (d.applies_to is null or u.role = any (d.applies_to)))     as assigned_count,
  (select count(*)
     from staff.outstanding_docs o
    where o.user_id = u.id)                                          as outstanding_count,
  (select max(a.signed_at)
     from staff.attestations a
    where a.user_id = u.id)                                          as last_signed_at
from staff.users u
where u.active;

grant select on staff.compliance_status to staff_app;


-- ========== staff-onboarding-seed.sql ==========

-- ============================================================
-- STARTER ONBOARDING PACKET
--
-- Run AFTER supabase/staff-onboarding.sql. Idempotent; safe to re-run.
-- Editing a document later means inserting a NEW version row, not
-- changing these — see the immutability note in staff-onboarding.sql.
--
-- TWO KINDS OF DOCUMENT ARE SEEDED HERE, AND THE DIFFERENCE MATTERS.
--
-- PUBLISHED (published_at set) — these state a legal requirement that
-- applies to the staff of any urgent care regardless of who owns it, and
-- cite the rule they come from. What the reader attests to is that they
-- understand the obligation and will work accordingly. Nothing here
-- describes any particular employer's internal procedure, so nothing here
-- is invented on an employer's behalf.
--
-- DRAFT (published_at null) — skeletons for the policies that are
-- genuinely the employer's own: attendance, social media, controlled
-- substances, incident reporting. Their content cannot be guessed and
-- must not be. They are NOT assigned to anyone and no one can sign them
-- until an administrator writes the real text and publishes it. A seeded
-- placeholder presented to staff as their employer's policy would make
-- the resulting signature worthless, which defeats the entire purpose of
-- collecting it.
--
-- These acknowledgements record that someone was informed. They are not a
-- substitute for hands-on training where a regulation requires it — in
-- particular OSHA bloodborne pathogens training under 29 CFR
-- 1910.1030(g)(2) must include an opportunity for interactive questions
-- and answers with a qualified trainer, and Pennsylvania mandated
-- reporter training for licensure must come from an approved provider.
-- ============================================================

insert into staff.policy_docs
  (org_slug, key, version, title, category, citation, summary, body_md,
   attestation, applies_to, renew_months, sort_order, published_at)
values

-- ---------- HIPAA PRIVACY ----------
('afc', 'hipaa-privacy', 1,
 'Patient privacy and the minimum necessary rule',
 'hipaa',
 '45 CFR 164.502(b), 164.514(d), 164.530(b), 164.530(e)',
 'What you may look at, what you may say, and what happens if you look at something you had no reason to see.',
$md$
## Why this exists

The HIPAA Privacy Rule requires every covered entity to train its workforce on
its privacy policies and to apply sanctions when they are broken
(45 CFR 164.530(b) and (e)). This document is that training record for you.

## Minimum necessary

When you use or disclose protected health information, you may only use or
see **the minimum necessary** to do the job in front of you
(45 CFR 164.502(b), 164.514(d)). In practice:

- Open a chart because a task requires it, never out of curiosity.
- Looking up a friend, a neighbour, a family member, a coworker, or yourself
  is a violation even if you change nothing and tell no one.
- Every access is logged. Audits are routine, not a reaction to suspicion.

## Talking about patients

- Not in the waiting room, not in the hallway, not in the elevator, not in the
  parking lot.
- Not to a patient's family member without confirming they are permitted to
  receive it.
- Not on social media, ever — including details you believe are anonymous.
  Town, age, injury, and time of day identify a person in a small community.

## If something goes wrong

Report a suspected privacy incident to your supervisor **the same day**. A
disclosure reported quickly is often containable; the notification duties in
45 CFR 164.400–414 run on a clock. You will not be disciplined for reporting
your own mistake promptly and honestly. You may be disciplined for hiding it.
$md$,
 'I understand the minimum necessary rule, that accessing a record I have no work reason to open is a violation, and that I must report a suspected privacy incident the same day I become aware of it.',
 null, 12, 10, now()),

-- ---------- HIPAA SECURITY ----------
('afc', 'hipaa-security', 1,
 'Logins, devices, and workstation security',
 'hipaa',
 '45 CFR 164.308(a)(5), 164.310(b), 164.310(c)',
 'Your login is you. Everything done with it is attributed to you.',
$md$
## Your credentials are yours alone

The Security Rule requires a security awareness and training program for all
workforce members (45 CFR 164.308(a)(5)). The core of it is simple:

- **Never share a password or badge**, including with a supervisor, and
  including "just for today."
- **Never work under someone else's session.** Every action is attributed to
  the account that performed it. If you use a coworker's login, their name is
  on what you did, and yours is on what they did.
- If you believe someone else has used your account, say so immediately.

## Workstations

Workstation use and security are specifically regulated
(45 CFR 164.310(b), (c)):

- Lock the screen when you step away, every time, including "just a second."
- Turn monitors so they are not readable from the waiting area.
- Do not install software on clinic machines.

## Phones and photos

- No patient information in personal text messages, personal email, or any
  consumer messaging app.
- No photographs inside clinical areas without an explicit clinical reason and
  a supervisor's approval. A photo taken for a legitimate reason still catches
  whatever is on the screen behind it.
- Do not save patient information to a personal device, cloud account, or USB
  drive.

## Email and phishing

Most breaches start with an ordinary-looking email. Confirm unexpected requests
for credentials, payment changes, or patient information through a second
channel before acting — a phone call to a number you already had, not the one
in the message.
$md$,
 'I understand that my login identifies me personally, that I must never share or use another person''s credentials, and that patient information must not be placed on personal devices or accounts.',
 null, 12, 20, now()),

-- ---------- OSHA BLOODBORNE PATHOGENS ----------
('afc', 'osha-bloodborne', 1,
 'Bloodborne pathogens, sharps, and exposure response',
 'osha',
 '29 CFR 1910.1030',
 'Universal precautions, safe sharps handling, and exactly what to do in the first minutes after a needlestick.',
$md$
## Universal precautions

Treat **all** human blood and other potentially infectious material as if it
is infectious (29 CFR 1910.1030(d)(1)). You do not get to decide which
patients warrant precautions, and you cannot tell by looking.

## Personal protective equipment

Gloves for any contact with blood, body fluids, mucous membranes, or broken
skin. Face and eye protection whenever splash or spatter is possible. Gowns
when clothing could be soaked through. Your employer must provide PPE at no
cost to you and must replace it as needed — if it is not available, that is a
problem to raise, not to work around.

## Sharps

- Never recap a needle by hand.
- Activate the safety device immediately, at the point of use.
- Dispose of sharps in an approved container at the point of use. Do not
  carry an unsheathed sharp across a room.
- Never overfill a sharps container or push anything down into one.

## Hepatitis B vaccination

The vaccination series must be offered to you at no cost within 10 working
days of assignment to duties with exposure risk (29 CFR 1910.1030(f)(2)). You
may decline it, and you may change your mind and receive it later at no cost.

## If you are exposed

An exposure is a needlestick, a cut with a contaminated object, or contact of
blood or body fluid with your eyes, nose, mouth, or broken skin.

1. **Wash immediately** — soap and running water for skin; flush eyes or
   mucous membranes with water or saline for several minutes.
2. **Report it immediately**, before the end of your shift, without exception.
   Post-exposure prophylaxis is time-sensitive and its effectiveness falls
   with delay.
3. A confidential medical evaluation and follow-up must be made available to
   you at no cost (29 CFR 1910.1030(f)(3)).
4. The event is recorded on the sharps injury log
   (29 CFR 1910.1030(h)(5)), which does not name you publicly.

You will never be penalized for reporting an exposure. Not reporting one puts
only you at risk.
$md$,
 'I understand universal precautions and safe sharps handling, I know that the hepatitis B vaccination must be offered to me at no cost, and I understand that I must report any exposure immediately and before the end of my shift.',
 null, 12, 30, now()),

-- ---------- OSHA HAZARD COMMUNICATION ----------
('afc', 'osha-hazcom', 1,
 'Chemical safety and hazard communication',
 'osha',
 '29 CFR 1910.1200',
 'Labels, safety data sheets, and where to find them without asking anyone.',
$md$
## The right to know

The Hazard Communication Standard (29 CFR 1910.1200) gives you the right to
know what chemicals you work with and how they can hurt you. It is your
employer's duty to make that information available and yours to use it.

## Labels

Every container must be labelled. A secondary container — a spray bottle you
filled yourself — must be labelled too, with the product identifier and the
hazard. An unlabelled bottle of clear liquid is a hazard on its own.

Pictograms you will see on the products used here: corrosion, exclamation
mark, flame, and health hazard. Learn the four; they carry most of the
meaning at a glance.

## Safety data sheets

An SDS must be readily accessible during every shift, without needing a
password, a supervisor, or a locked cabinet. Find out where they are kept in
your clinic **today**, not on the day you need one. Section 4 is first aid;
section 8 is the protective equipment required.

## Working safely

- Never mix cleaning products. Bleach with ammonia or with acid produces a
  toxic gas, and several common cleaners contain one or the other.
- Follow the contact time on disinfectant labels. A surface wiped dry too
  early has not been disinfected.
- Ventilate as the label directs.

## Spills and exposures

Know where the eyewash station and spill kit are. For a chemical splash to
the eye, flush for 15 minutes and get help — do not stop early because it
feels better. Report every chemical exposure the same way you would report a
bloodborne exposure.
$md$,
 'I know where safety data sheets are kept in my clinic and how to reach them during any shift, I understand secondary containers must be labelled, and I understand I must report chemical exposures.',
 null, 12, 40, now()),

-- ---------- EMERGENCY PROCEDURES ----------
('afc', 'emergency-procedures', 1,
 'Emergency procedures and evacuation',
 'operations',
 '29 CFR 1910.38',
 'What you personally do first — before you look for someone more senior.',
$md$
## Why this is your job, not someone else's

An emergency action plan is required to be reviewed with each employee when
they are assigned to their role (29 CFR 1910.38(f)). The plan only works if
the first person to notice acts, and in an urgent care that is usually
whoever is closest — not whoever is most senior.

## Medical emergency in the building

- Call for help out loud before you do anything else. Do not go looking for
  someone quietly.
- Know where the AED is and that it talks you through its own use.
- Know where the emergency kit and oxygen are kept.
- Someone must meet EMS at the door and bring them in. That job is real and
  is often forgotten.

## Fire

**R.A.C.E.** — Rescue anyone in immediate danger, Alarm, Contain by closing
doors, Extinguish only if the fire is small and you have a clear exit behind
you.

**P.A.S.S.** for an extinguisher — Pull, Aim at the base, Squeeze, Sweep.

Never let a fire get between you and the way out.

## Evacuation

Know the two nearest exits from wherever you are standing. Know the assembly
point outside. Do not use the elevator. Patients in rooms are your
responsibility on the way out — nobody is left because everyone assumed
someone else had checked.

## Violent or threatening person

Distance first, then a door between you and them, then call. Do not attempt
to physically manage a violent person alone. De-escalate with a calm voice
and open hands; give a person a way out of the room rather than blocking it.

## Severe weather and power loss

Move away from glass. Know which outlets are on emergency power and which
refrigerators hold temperature-sensitive stock, because that clock starts the
moment the power does not come back.
$md$,
 'I know the location of the nearest exits, the AED, the fire extinguishers, and the assembly point for my clinic, and I understand my own first actions in a medical emergency, a fire, and an evacuation.',
 null, 12, 50, now()),

-- ---------- MANDATED REPORTING (PENNSYLVANIA) ----------
('afc', 'mandated-reporting-pa', 1,
 'Mandated reporting of suspected abuse (Pennsylvania)',
 'clinical',
 '23 Pa. C.S. § 6311; 35 P.S. § 10225.701 et seq.',
 'You report suspicion directly. You do not need proof, and you do not delegate it.',
$md$
## You are a mandated reporter

Under 23 Pa. C.S. § 6311, individuals who come into contact with children in
the course of their employment in a healthcare facility are **mandated
reporters** of suspected child abuse. This includes clinical and non-clinical
staff who have contact with patients.

## What triggers a report

You must report when you have **reasonable cause to suspect** a child is a
victim of abuse. Three things follow from that wording, and each is the point
where people get it wrong:

- **Suspicion is the standard, not proof.** Investigating is somebody else's
  job. Waiting until you are sure is itself a failure to report.
- **You report personally.** Telling a supervisor does not discharge your
  duty (23 Pa. C.S. § 6311(c)). A mandated reporter who tells a manager and
  assumes it was handled has still not reported.
- **You cannot be prevented from reporting**, and an employer may not
  retaliate against you for making a report in good faith.

## How

ChildLine — **1-800-932-0313**, available 24 hours — or electronically
through the Child Welfare Portal. An oral report is followed by a written
report as the statute requires. Report first, document after.

## Older adults

Pennsylvania's Older Adults Protective Services Act (35 P.S. § 10225.701 et
seq.) imposes reporting duties on employees of covered facilities regarding
suspected abuse, neglect, exploitation, or abandonment of an older adult.
Whether a given urgent care is a covered "facility" is a legal question for
your administrator — ask, and know the answer before you need it. Suspected
abuse of an older adult is reported to the statewide elder abuse hotline at
**1-800-490-8505**.

## Not a substitute for approved training

This acknowledgement records that you understand the duty. Pennsylvania
requires mandated reporter training from an approved provider for many
professional licences; this document does not satisfy that requirement.
$md$,
 'I understand that I am personally a mandated reporter, that reasonable suspicion — not proof — is the standard, that telling a supervisor does not discharge my duty, and that I know how to make a report directly.',
 null, 24, 60, now()),

-- ---------- MASTER ACKNOWLEDGEMENT ----------
('afc', 'employee-acknowledgement', 1,
 'Employee acknowledgement',
 'hr',
 null,
 'The signature that ties the packet together.',
$md$
## What you are signing

You have been given each of the documents in this packet, in full, and had the
opportunity to read them before signing. Each signature is recorded with the
date and time, and with a fingerprint of the exact text you were shown, so
what you agreed to can be produced later exactly as it read on the day.

## What this signature means

- You have read the documents in this packet.
- Where something was unclear, you asked, or you understand that you may ask
  at any time and that asking is expected rather than tolerated.
- You will follow these policies, and you will say so promptly if you cannot,
  rather than working around them quietly.

## What it does not mean

- It is **not** an employment contract and does not change your employment
  status.
- It does **not** waive any right you have, including your right to report a
  safety or legal concern to a regulator.
- It does **not** mean you agree with every policy — only that you have been
  told what they are.

## Keeping it current

Policies change. When a document is revised you will be asked to review the
new version, and your earlier signature stays on file against the version you
originally signed. Some documents renew annually whether or not they have
changed.

You may view and print your own complete compliance record at any time.
$md$,
 'I acknowledge that I have received and read each document in this onboarding packet, that I have had the opportunity to ask questions about them, and that I agree to follow them.',
 null, 12, 999, now())

on conflict (org_slug, key, version) do nothing;

-- ============================================================
-- DRAFTS — the employer's own policies.
--
-- Not assigned, not signable. An administrator replaces the body with the
-- real policy and publishes it. The scaffolding says what the document
-- has to cover, so nobody has to start from a blank page — but no
-- employee is ever shown this text as though it were their employer's
-- rule.
-- ============================================================

insert into staff.policy_docs
  (org_slug, key, version, title, category, summary, body_md, applies_to,
   renew_months, sort_order, published_at)
values

('afc', 'attendance-and-scheduling', 1,
 'Attendance, scheduling, and call-outs', 'hr',
 'DRAFT — replace with your own policy before publishing.',
$md$
> **This is a draft skeleton, not a policy.** It is not assigned to anyone
> and cannot be signed until an administrator replaces this text and
> publishes it.

Cover at minimum:

- Who to notify for an unplanned absence, by what method, and how far ahead.
- Shift start expectations and what counts as late.
- How shift swaps are approved and by whom.
- Time-off requests: how far in advance, and how conflicts are resolved.
- Meal and rest breaks, and what to do when patient volume makes a break
  impossible.
- No-call/no-show consequences, stated plainly.
$md$,
 null, null, 200, null),

('afc', 'social-media-and-photography', 1,
 'Social media, photography, and public statements', 'hr',
 'DRAFT — replace with your own policy before publishing.',
$md$
> **This is a draft skeleton, not a policy.** It is not assigned to anyone
> and cannot be signed until an administrator replaces this text and
> publishes it.

Cover at minimum:

- No patient information on personal accounts, including details you believe
  are de-identified.
- Photography and video inside the clinic: when, with whose approval, on which
  device, and where the file may be stored.
- Whether staff may identify their employer on personal accounts, and any
  disclaimer expected.
- Who may speak to press or respond to online reviews. Reviews are the usual
  trap — a reply confirming that someone was a patient is a disclosure, even
  when the patient posted first.
- Note for whoever drafts this: employees have a legally protected right to
  discuss wages and working conditions with each other, and a policy that
  reads as though it forbids that is unenforceable and creates its own
  liability. Have counsel review the final wording.
$md$,
 null, null, 210, null),

('afc', 'controlled-substances', 1,
 'Controlled substances: storage, counts, and waste', 'clinical',
 'DRAFT — must be written against your own DEA registration before publishing.',
$md$
> **This is a draft skeleton, not a policy.** It is not assigned to anyone
> and cannot be signed until an administrator replaces this text and
> publishes it.

This one cannot be borrowed from anywhere. It has to be written against your
own DEA registration, your state requirements, and your actual physical
setup. Cover at minimum:

- Which schedules are kept on site, and where.
- Who holds keys or access codes, and how that list is kept current.
- Shift-change count procedure, who performs it, and where it is recorded.
- Wastage: two-person witness, documentation, and what happens to a partial
  vial.
- Discrepancy procedure — who is notified, how quickly, and what is not done
  (namely, resolving it quietly).
- Prescription pad and e-prescribing credential security.
- Record retention periods and where the records live.
$md$,
 array['org_admin','clinical_lead']::staff.user_role[], null, 220, null),

('afc', 'incident-reporting', 1,
 'Incident reporting and escalation', 'operations',
 'DRAFT — replace with your own policy before publishing.',
$md$
> **This is a draft skeleton, not a policy.** It is not assigned to anyone
> and cannot be signed until an administrator replaces this text and
> publishes it.

Cover at minimum:

- What counts as an incident: patient injury, staff injury, medication error,
  near miss, equipment failure, privacy event, aggression or threat.
- The form, where it lives, and the deadline for filing it.
- Who is notified immediately versus at the end of shift.
- An explicit non-retaliation statement for good-faith reports, including
  reports of your own error. Without this sentence the rest of the policy
  collects nothing, because people do not report themselves into a
  punishment.
- Who reviews incidents, on what cadence, and how the outcome gets back to
  the person who reported.
$md$,
 null, null, 230, null)

on conflict (org_slug, key, version) do nothing;


-- ========== staff-logs.sql ==========

-- ============================================================
-- OPERATIONAL LOGS — schema additions
--
-- Run AFTER supabase/staff-schema.sql. Idempotent; safe to re-run.
--
-- The log tables (form_templates / form_instances / form_responses) already
-- exist from staff-schema.sql. This file adds what turning them into an
-- actual daily workflow needs: a URL slug, a shift slot, and the
-- out-of-range fields.
--
-- DESIGN NOTE — instances are created on demand, not by a nightly job.
-- A cron that pre-creates today's rows is one more thing that can fail
-- silently at 3am and leave a clinic with no logs to fill in. Instead the
-- row is created the moment someone opens the form, keyed on
-- (template, date, slot) so opening it twice is the same row.
-- ============================================================

-- A stable, readable identifier for the URL: /staff/logs/temp-fridge.
-- The display name can be reworded without breaking a bookmark or an
-- entry in someone's muscle memory.
alter table staff.form_templates add column if not exists slug text;
alter table staff.form_templates add column if not exists description text;
-- Which shifts this form is due in. Empty means once a day, any time.
alter table staff.form_templates add column if not exists slots text[] not null default '{}';
-- Ordering on the "today" screen. Opening checks before closing checks.
alter table staff.form_templates add column if not exists sort_order integer not null default 100;

create unique index if not exists staff_templates_slug
  on staff.form_templates (org_slug, slug) where slug is not null;

-- 'am' | 'pm' | '' — part of the identity of an instance, because a
-- twice-daily fridge check is two separate records on the same date and
-- the original unique constraint could only hold one.
alter table staff.form_instances add column if not exists slot text not null default '';

do $$ begin
  alter table staff.form_instances drop constraint if exists form_instances_template_id_due_date_key;
exception when undefined_object then null;
end $$;

create unique index if not exists staff_instances_identity
  on staff.form_instances (template_id, due_date, slot);

-- Out-of-range handling.
--
-- A value outside its threshold is not just a flag on a row — it is the
-- whole reason a temperature log exists. The corrective action is stored
-- alongside the answers rather than inside them so it can be queried,
-- alerted on, and shown to a surveyor without parsing JSON.
alter table staff.form_responses add column if not exists has_out_of_range boolean not null default false;
alter table staff.form_responses add column if not exists out_of_range_fields text[] not null default '{}';
alter table staff.form_responses add column if not exists corrective_action text;

-- A response that reports an out-of-range value MUST carry a corrective
-- action. Enforced here and not only in the form, because "the technician
-- can't submit without it" and "the record cannot exist without it" are
-- different guarantees, and only the second one survives a future API,
-- an import, or a bug in the client.
do $$ begin
  alter table staff.form_responses
    add constraint staff_response_needs_corrective_action
    check (
      not has_out_of_range
      or (corrective_action is not null and length(btrim(corrective_action)) >= 3)
    );
exception when duplicate_object then null;
end $$;

-- One live response per instance.
--
-- Without this a form could be filed twice for the same shift — I did it
-- by accident while testing — and the board would show the same log
-- twice with no way to tell which reading was the real one. A correction
-- is a new row pointing at the one it supersedes (supersedes_id), which
-- is why the index is partial rather than a plain unique constraint.
create unique index if not exists staff_responses_one_live
  on staff.form_responses (instance_id) where supersedes_id is null;

create index if not exists staff_responses_flagged
  on staff.form_responses (org_slug, submitted_at desc) where has_out_of_range;

-- ============================================================
-- TODAY'S BOARD
--
-- Every active template crossed with the slots it is due in, left-joined
-- to whatever has been submitted for today. security_invoker so it reads
-- under the caller's org context — see the note in staff-onboarding.sql
-- about views otherwise running as their owner and bypassing RLS.
-- ============================================================

-- Dropped first so this file can be re-run after a later migration has
-- added a column to this view. CREATE OR REPLACE cannot drop a column,
-- so replacing the extended view with this original definition fails
-- with "cannot drop columns from view" — which broke the combined
-- setup file's second run while the first run was clean.
drop view if exists staff.todays_logs cascade;
create view staff.todays_logs
with (security_invoker = true) as
select
  t.org_slug,
  t.id            as template_id,
  t.slug,
  t.name,
  t.description,
  t.category,
  t.frequency,
  t.sort_order,
  s.slot,
  r.id            as response_id,
  r.submitted_at,
  r.submitted_by,
  r.has_out_of_range,
  u.legal_name    as submitted_by_name,
  u.email         as submitted_by_email
from staff.form_templates t
-- '{}' means "once, any time of day", which unnest would turn into no
-- rows at all — so an empty slots array becomes a single empty slot.
cross join lateral unnest(
  case when cardinality(t.slots) = 0 then array[''] else t.slots end
) as s(slot)
left join staff.form_instances i
  on i.template_id = t.id and i.due_date = current_date and i.slot = s.slot
left join staff.form_responses r
  on r.instance_id = i.id and r.supersedes_id is null
left join staff.users u on u.id = r.submitted_by
where t.active;

grant select on staff.todays_logs to staff_app;


-- ========== staff-logs-seed.sql ==========

-- ============================================================
-- THE STANDARD LOG SET
--
-- Run AFTER supabase/staff-logs.sql. Idempotent; safe to re-run.
--
-- Every threshold below comes from a published standard, and each one is
-- named in the form's `standard` line so the person filling it in can see
-- what they are checking against without looking anything up. Where a
-- number depends on the specific clinic — which fridges exist, which
-- assays are run, which drugs are stocked — the options are a starting
-- point an administrator edits, not a fact about this clinic that
-- anybody invented.
--
-- NOT INCLUDED HERE ON PURPOSE: "clinical/financial separation". It is an
-- annual staff acknowledgement, not something anybody measures on a
-- shift, so it belongs in the onboarding packet where it gets a signature
-- against a document version. Putting it here would have produced a
-- checkbox with no signature behind it.
-- ============================================================

insert into staff.form_templates
  (org_slug, slug, name, description, category, frequency, slots, sort_order, schema_json)
values

('afc', 'crash-cart', 'Crash cart & AED',
 'Seal, AED self-test, oxygen pressures, suction.',
 'clinical', 'daily', array['am'], 10,
$json$
{
  "standard": "Seal intact and matching the log. AED self-test green. Both O2 cylinders above 1000 PSI. Suction pulls.",
  "fields": [
    { "id": "seal_number", "label": "Breakaway seal number", "type": "text",
      "placeholder": "e.g. 004821",
      "help": "Read it off the tag. If it does not match yesterday's, the cart was opened." },
    { "id": "seal_intact", "label": "Seal intact", "type": "boolean", "expected": true },
    { "id": "aed_status", "label": "AED self-test indicator", "type": "select",
      "options": ["Green check", "Red / flashing", "Audible alarm", "No indication"],
      "failing": ["Red / flashing", "Audible alarm", "No indication"] },
    { "id": "aed_pads_expiry", "label": "Electrode pad expiry", "type": "date" },
    { "id": "o2_primary_psi", "label": "Primary O2 cylinder", "type": "number",
      "unit": "PSI", "min": 1000, "max": 2400, "step": 10 },
    { "id": "o2_backup_psi", "label": "Backup O2 cylinder", "type": "number",
      "unit": "PSI", "min": 1000, "max": 2400, "step": 10 },
    { "id": "suction_ok", "label": "Suction unit pulls", "type": "boolean", "expected": true }
  ]
}
$json$::jsonb),

('afc', 'temp-fridge', 'Refrigerator temperatures',
 'Current, 24-hour minimum and maximum for each unit.',
 'clinical', 'per_shift', array['am','pm'], 20,
$json$
{
  "standard": "Vaccine storage 36-46 °F (2-8 °C). Any excursion means quarantine the stock and call the manufacturer before discarding anything.",
  "fields": [
    { "id": "unit", "label": "Unit", "type": "select",
      "options": ["Vaccine fridge", "Medication fridge", "Lab reagent fridge"] },
    { "id": "current_f", "label": "Current", "type": "number",
      "unit": "°F", "min": 36, "max": 46, "step": 0.1 },
    { "id": "min_24h_f", "label": "24-hour minimum", "type": "number",
      "unit": "°F", "min": 36, "max": 46, "step": 0.1 },
    { "id": "max_24h_f", "label": "24-hour maximum", "type": "number",
      "unit": "°F", "min": 36, "max": 46, "step": 0.1 },
    { "id": "memory_reset", "label": "Min/max memory reset after reading", "type": "boolean",
      "expected": true,
      "help": "Reset it, or tomorrow's numbers are today's all over again." }
  ]
}
$json$::jsonb),

('afc', 'narcotics-count', 'Controlled substance count',
 'Physical count at shift change, with a witness.',
 'clinical', 'per_shift', array['am','pm'], 30,
$json$
{
